if (items.length === 0) {
  // Rien à agréger
  return [];
}

// Regrouper par (sensor_id, parameter)
const groups = {};

for (const item of items) {
  const row = item.json;
  const sensorId = row.sensor_id || 'unknown';
  const parameter = row.parameter || 'pm25';
  const value = Number(row.value);
  const ts = new Date(row.datetime_utc);

  if (Number.isNaN(value) || isNaN(ts.getTime())) {
    continue;
  }

  // Heure arrondie à l'heure (UTC)
  const hour = new Date(ts);
  hour.setMinutes(0, 0, 0);
  const hourKey = hour.toISOString();

  const key = `${sensorId}__${parameter}__${hourKey}`;

  if (!groups[key]) {
    groups[key] = {
      sensor_id: sensorId,
      parameter,
      hour_utc: hourKey,
      sum: 0,
      max: value,
      count: 0
    };
  }

  const g = groups[key];
  g.sum += value;
  if (value > g.max) {
    g.max = value;
  }
  g.count += 1;
}

const out = [];
for (const key of Object.keys(groups)) {
  const g = groups[key];
  const avg = g.count > 0 ? g.sum / g.count : 0;
  out.push({
    json: {
      sensor_id: g.sensor_id,
      parameter: g.parameter,
      hour_utc: g.hour_utc,
      avg_value: avg,
      max_value: g.max,
      samples_count: g.count
    }
  });
}

return out;
